// One job-feed run per role x city from the Searches tab, for the current week (weeks start on Monday).
// Skips searches already stored for this week (unless reRunSameWeek) and searches whose run is still RUNNING. At most maxSearchesPerRun runs.
// A webhook execution only collects. Stops with a message when no search is usable (no Apify cost).
const s = $('Settings').first().json;
const openRuns = () => $('Read Runs tab').all().map(i => i.json)
  .filter(r => /^(RUNNING|READY)$/i.test(String(r.status || '').trim()) && String(r.run_url || '').trim())
  .map(r => ({ id: String(r.run_url).trim().replace(/\/+$/, '').split('/').pop(), run_url: String(r.run_url).trim(), search: String(r.search || ''), mode: String(r.mode || ''), status: String(r.status).trim().toUpperCase() }));
// Set when this execution was started by the "Apify run finished" webhook: only that run is collected, and nothing new is started.
let hookRun = '';
try { hookRun = String($('Apify run finished').first().json.body.runId || ''); } catch (e) {}
const clean = v => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
const week = $now.startOf('week').toFormat('yyyy-LL-dd');
const rows = $('Read Searches tab').all().map(i => i.json)
  .filter(r => clean(r.role) && clean(r.city) && !/^(no|false|0|off|nein)$/i.test(clean(r.active)));
if (!hookRun) {
  if (!rows.length) throw new Error("No active search. Open the Sheet, tab 'Searches', and add rows: role, city, country (2 letters, for example DE), active = yes.");
  const bad = rows.find(r => !/^[A-Za-z]{2}$/.test(clean(r.country)));
  if (bad) throw new Error("The country of '" + clean(bad.role) + ' in ' + clean(bad.city) + "' must be a 2-letter code (DE, CH, AT, US, GB ...).");
}
const done = new Set($('Read History tab').all().map(i => String(i.json.key || '').toLowerCase()));
const open = new Set(openRuns().filter(r => r.mode === 'job market').map(r => r.search));
const cap = Math.max(1, Math.round(Number(s.maxAdsPerSearch) || 30));
const days = Number(s.postedWithinDays) > 0 ? Number(s.postedWithinDays) : 7;
const starts = [];
const seen = new Set();
for (const r of rows) {
  if (hookRun || starts.length >= Math.max(1, Math.round(Number(s.maxSearchesPerRun) || 4))) break;
  const role = clean(r.role), city = clean(r.city), cc = clean(r.country).toUpperCase();
  const key = [week, role, city, cc].join('|').toLowerCase();
  const search = [role, city, cc, week].join(' | ');
  if (seen.has(key) || (done.has(key) && s.reRunSameWeek !== true) || open.has(search)) continue;
  seen.add(key);
  starts.push({ search, mode: 'job market', body: { keywords: [role], countries: [cc], location: city, radiusKm: Math.round(Number(s.radiusKm) || 25),
    postedWithinDays: days, sortBy: 'newest', maxResultsTotal: cap, minRelevanceScore: Math.round(Number(s.minRelevanceScore) || 0),
    includeGlobalBoards: s.includeGlobalBoards !== false, includeJobDetails: false } });
}
return [{ json: { starts } }];

// One Apify run per search. The start query is built here (timeout, memory, cost cap, optional ad-hoc webhook).
const s = $('Settings').first().json;
const hook = String(s.webhookUrl || '').trim();
const b64 = t => typeof Buffer !== 'undefined' ? Buffer.from(t, 'utf8').toString('base64') : btoa(unescape(encodeURIComponent(t)));
const query = { waitForFinish: 0, timeout: Math.round((Number(s.apifyRunTimeoutMinutes) || 240) * 60), memory: 1024, maxTotalChargeUsd: Number(s.maxCostPerRunUsd) || 0.25 };
if (hook) query.webhooks = b64(JSON.stringify([{ eventTypes: ['ACTOR.RUN.SUCCEEDED', 'ACTOR.RUN.FAILED', 'ACTOR.RUN.ABORTED', 'ACTOR.RUN.TIMED_OUT'],
  requestUrl: hook, payloadTemplate: '{"runId": {{resource.id}}, "status": {{resource.status}}}' }]));
return $input.first().json.starts.map(x => ({ json: { ...x, query } }));

// One Runs-tab row per started run. A run that could not be started is logged too (status FAILED, with the reason).
const src = $('One item per job market search').all();
const now = $now.toFormat('yyyy-LL-dd HH:mm');
return $input.all().map((it, i) => {
  const r = (it.json && it.json.data) || it.json || {}, s = (src[i] || { json: {} }).json;
  const e0 = (it.json && it.json.error) || r.error;
  const err = e0 ? String((e0 && (e0.message || e0.description)) || e0) : (r.id ? '' : String(r.message || 'no run ID returned'));
  return { json: { started_at: now, search: s.search || '', mode: s.mode || '', status: r.id ? 'RUNNING' : 'FAILED', jobs: '', charged_usd: '',
    run_url: r.id ? 'https://console.apify.com/view/runs/' + r.id : '', collected_at: r.id ? '' : now, note: r.id ? '' : 'could not start: ' + err, run_id: r.id || '' } };
});

// Everything to poll: the runs started just now plus the runs of earlier executions that are still RUNNING (for this part of the workflow).
const openRuns = () => $('Read Runs tab').all().map(i => i.json)
  .filter(r => /^(RUNNING|READY)$/i.test(String(r.status || '').trim()) && String(r.run_url || '').trim())
  .map(r => ({ id: String(r.run_url).trim().replace(/\/+$/, '').split('/').pop(), run_url: String(r.run_url).trim(), search: String(r.search || ''), mode: String(r.mode || ''), status: String(r.status).trim().toUpperCase() }));
const mine = ['job market'];
const hook = String($('Settings').first().json.webhookUrl || '').trim();
let hookRun = '';
try { hookRun = String($('Apify run finished').first().json.body.runId || ''); } catch (e) {}
let fresh = [];
// With a webhook URL set, new runs are not watched here: Apify calls the webhook when they finish.
if (!hook) try { fresh = $('Log the new job market runs').all().map(i => i.json).filter(r => r.run_id).map(r => ({ id: r.run_id, run_url: r.run_url, search: r.search, mode: r.mode, status: 'RUNNING' })); } catch (e) {}
const seen = new Set();
const out = [];
for (const r of [...fresh, ...openRuns().filter(r => mine.includes(r.mode) && (!hookRun || r.id === hookRun))]) { if (!r.id || seen.has(r.id)) continue; seen.add(r.id); out.push({ json: r }); }
return out;

// Sort the runs by outcome. Keeps looping while a run is still open and Settings.maxWaitMinutes is not used up.
const s = $('Settings').first().json;
const maxPolls = String(s.webhookUrl || '').trim() ? 0 : Math.floor((Number(s.maxWaitMinutes) >= 0 ? Number(s.maxWaitMinutes) : 30) * 60 / 70);
const polls = $runIndex + 1;
const base = $('Runs to watch (job market)').all().map(i => i.json);
const got = $input.all().map(i => i.json || {});
// What the run charges you: pay-per-event actors = sum(chargedEventCounts x event price) (+ platform usage only when the run bills usage to the user); other runs = usageTotalUsd.
const chargedOf = r => {
  const ev = (((r.pricingInfo || {}).pricingPerEvent || {}).actorChargeEvents) || null;
  if (!ev || !/PAY_PER_EVENT/i.test(String((r.pricingInfo || {}).pricingModel || ''))) return r.usageTotalUsd;
  const cnt = r.chargedEventCounts || {};
  let t = 0;
  for (const k of Object.keys(cnt)) t += (Number(cnt[k]) || 0) * (Number((ev[k] || {}).eventPriceUsd) || 0);
  if (String(r.platformUsageBillingModel || '').toUpperCase() === 'USER') t += Number(r.usageTotalUsd) || 0;
  return t;
};
const isOpen = st => ['READY', 'RUNNING', 'TIMING-OUT', 'ABORTING'].includes(st);
const rows = base.map((b, i) => { const r = got[i] || {}; return { ...b, status: String(r.status || (r.error ? 'UNKNOWN' : b.status || 'UNKNOWN')).toUpperCase(), defaultDatasetId: r.defaultDatasetId || '',
  charged: chargedOf(r), jobs: (r.chargedEventCounts || {})['orchestrator-unique-job'], note: r.error ? 'could not read the run status: ' + String((r.error && r.error.message) || r.error) : '' }; });
const stillRunning = rows.some(r => isOpen(r.status)) && polls <= maxPolls;
return rows.map(r => ({ json: { ...r, stillRunning, polls, outcome: r.status === 'SUCCEEDED' ? 'done' : isOpen(r.status) ? 'running' : 'problem' } }));

// Runs of this execution whose dataset was just processed: mark them collected, so they are never processed twice.
const fmt = u => (u == null || u === '' || isNaN(Number(u))) ? '' : String(Math.round(Number(u) * 10000) / 10000);
const now = $now.toFormat('yyyy-LL-dd HH:mm');
return $('Check the job market runs').all().map(i => i.json).filter(r => r.outcome === 'done' && !r.stillRunning)
  .map(r => ({ json: { run_url: r.run_url, status: 'SUCCEEDED', jobs: r.jobs == null ? '' : r.jobs, charged_usd: fmt(r.charged), collected_at: now, note: '' } }));

const fmt = u => (u == null || u === '' || isNaN(Number(u))) ? '' : String(Math.round(Number(u) * 10000) / 10000);
const r = $json;
const now = $now.toFormat('yyyy-LL-dd HH:mm');
const note = r.status === 'UNKNOWN' ? (r.note || 'could not read the run status (deleted or expired?)') : 'The run ended with status ' + r.status + '. Open run_url to see why. Nothing was collected from it.';
return { json: { run_url: r.run_url, status: r.status, jobs: '', charged_usd: fmt(r.charged), collected_at: now, note } };

// Turns each collected run into one History row and one Summary row (role x city), compared with the last stored week.
// ads = the number of unique jobs job-feed delivered for that run (dataset item count). It stops at maxAdsPerSearch: capped = yes means "at least this many".
const s = $('Settings').first().json;
const runs = $('Check the job market runs').all().map(i => i.json).filter(r => r.outcome === 'done' && !r.stillRunning);
const cap = Math.max(1, Math.round(Number(s.maxAdsPerSearch) || 30));
const days = Number(s.postedWithinDays) > 0 ? Number(s.postedWithinDays) : 7;
const num = v => (v === '' || v == null || isNaN(Number(v))) ? null : Number(v);
const r2 = v => Math.round(v * 100) / 100;
// A text starting with = + - @ gets a leading apostrophe so Google Sheets keeps it as text.
const safe = v => { v = String(v == null ? '' : v).trim(); return /^[=+\-@]/.test(v) ? "'" + v : v; };
const now = $now.toFormat('yyyy-LL-dd HH:mm');
const hist = $('Read History tab').all().map(i => i.json).filter(r => r.week && r.role);
const pairKey = (role, city, cc) => [role, city, cc].join('|').toLowerCase();
const history = [], summary = [];
$input.all().forEach((it, i) => {
  const run = runs[i];
  if (!run) return;
  const [role, city, cc, week] = String(run.search || '').split(' | ');
  const d = (it.json && it.json.data) || it.json || {};
  const ads = num(d.itemCount);
  if (!role || !week || ads == null) return;
  const pk = pairKey(role, city, cc);
  const prev = hist.filter(h => pairKey(h.role, h.city, h.country) === pk && String(h.week) < week && num(h.ads) != null)
    .sort((a, b) => String(a.week).localeCompare(String(b.week))).pop();
  const pa = prev ? num(prev.ads) : null;
  const capped = ads >= cap;
  const change = pa == null ? '' : ads - pa;
  const pct = pa ? r2((ads - pa) / pa * 100) : '';
  const wasCapped = !!prev && String(prev.capped) === 'yes';
  const trend = pa == null ? 'first week' : ((capped || wasCapped) && ads === pa) ? 'capped' : ads > pa ? 'up' : ads < pa ? 'down' : 'same';
  history.push({ week, checked_at: now, role: safe(role), city: safe(city), country: cc, ads, capped: capped ? 'yes' : 'no', cap, posted_within_days: days, run_url: run.run_url || '', key: [week, role, city, cc].join('|').toLowerCase() });
  summary.push({ role: safe(role), city: safe(city), country: cc, week, ads, capped: capped ? 'yes' : 'no', previous_week: prev ? prev.week : '', previous_ads: pa == null ? '' : pa,
    change, change_pct: pct, trend, key: pk });
});
return [{ json: { history, summary, count: history.length } }];
